import React from 'react';
import { useIntl } from 'react-intl';

import { DownloadIcon } from '@dynatrace/strato-icons';

import { DownloadDataMenuContents } from './DownloadDataMenuContents.js';
import { Button } from '../../buttons/button/Button.js';
import { Menu } from '../../navigation/menu/Menu.js';
import { Tooltip } from '../../overlays/tooltip/Tooltip.js';
import { dataTableMessages } from '../DataTable/messages.js';

/**
 * DataTable toolbar component for downloading the table data. Contains
 * menus with the options for downloading all, page or selected data.
 * Uses the DataTableContext.
 *
 * @returns DownloadData component
 */
export const DownloadData = () => {
  const intl = useIntl();

  const tooltipTextAndButtonLabel = intl.formatMessage(
    dataTableMessages.downloadButtonLabel,
  );

  return (
    <Menu>
      <Tooltip text={tooltipTextAndButtonLabel}>
        <Menu.Trigger>
          <Button variant="default" aria-label={tooltipTextAndButtonLabel}>
            <Button.Prefix>
              <DownloadIcon />
            </Button.Prefix>
          </Button>
        </Menu.Trigger>
      </Tooltip>
      <DownloadDataMenuContents />
    </Menu>
  );
};

DownloadData.displayName = 'DataTable.DownloadData';
